        "sampleValue": "存储快满"
      }
    },
    "thumbs": {
      "first": {
        "icon": {
          "type": "string",
          "description": "第一张缩略入口的文字符号。",
          "sampleValue": "山"
        },
        "label": {
          "type": "string",
          "description": "第一张缩略入口的短标签。",
          "sampleValue": "今日"
        }
      },
      "second": {
        "icon": {
          "type": "string",
          "description": "第二张缩略入口的文字符号。",
          "sampleValue": "人"
        },
        "label": {
          "type": "string",
          "description": "第二张缩略入口的短标签。",
          "sampleValue": "人物"
        }
      },
      "third": {
        "icon": {
          "type": "string",
          "description": "第三张缩略入口的文字符号。",
          "sampleValue": "星"
        },
        "label": {
          "type": "string",
          "description": "第三张缩略入口的短标签。",
          "sampleValue": "收藏"
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/cloudy.png",
      "description": "云朵组合天气图标，适合在深绿相册管理卡片中作为当前天气辅助识别。"
    }
  ]
}

